{
  "stages": {
    "prototype": {
      "level": 4,
      "rationale": "Throwaway code is for learning, so speed matters more than maintainability and AI can generate freely. Keep real customer data, credentials, and proprietary secrets out of prompts, and treat the result as disposable."
    },
    "proof-of-concept": {
      "level": 3,
      "rationale": "A stakeholder or investor demo carries reputational risk and often becomes the seed of real code, so selectively review risky paths and verify the demo behavior. Mark it as scratch code and require a rewrite or full review before it graduates."
    },
    "mvp": {
      "level": 3,
      "rationale": "Real early users mean real data, outages, and support costs, so AI can write most code but a person must review risky changes and verify behavior with tests. Authentication, payments, privacy, and data-integrity paths should get line-by-line review."
    },
    "production": {
      "level": 2,
      "rationale": "Paying customers and an on-call team make hidden defects expensive, so every AI-generated change needs line-by-line human review plus tests before release. AI can accelerate drafting and refactoring, but accountability stays with the reviewer."
    },
    "critical": {
      "level": 1,
      "rationale": "In regulated or safety-critical systems, AI may help brainstorm and suggest, but a human must author or rewrite every line and follow formal verification and change-control processes. Use level 0 if the applicable standard or regulator prohibits AI-generated code altogether."
    }
  },
  "summary": "Use AI most aggressively for disposable exploration, then tighten review as code acquires users, revenue, and regulatory obligations. No stage beyond prototype should accept code unread, and critical systems should preserve explicit human authorship and traceability."
}

